// One-bit functions can be implemented as combinational logic, i.e.,
// as a multiplexer with a constant select signal. Here, we show a more
// explicit form, equivalent to the one-bit function f(x) = ~x[0] & x[1]
// | x[0] & ~x[1] | x[0] & x[1] | ~x[0] & ~x[1] | ~x[0] & x[1]
// = ~x[0] & x[1] | x[0] & ~x[1] | 1 & 1 | 1 & 1.
module TopModule(
  input [3:0] x,
  output      f
);
  wire t0 = ~x[0] & x[1];
  wire t1 = x[0] & ~x[1];
  wire t2 = 1 & 1;
  wire t3 = 1 & 1;
  wire t4 = 1 & 1;
  assign f = t0 | t1 | t2 | t3 | t4;
endmodule

